(function() {
  try {
    if (!window.__NEXT_DATA__ || !window.__NEXT_DATA__.props || !window.__NEXT_DATA__.props.pageProps) {
      return { error: 'next_data_missing' };
    }
    var root = window.__NEXT_DATA__.props.pageProps;
    var vehicleDetails = root && root.forProviders && root.forProviders.forVehicleContext && root.forProviders.forVehicleContext.vehicleDetails;
    if (!vehicleDetails) {
      return { error: 'vehicle_details_missing' };
    }
    var canonical = (document.querySelector('link[rel="canonical"]') || {}).href || window.location.href;
    return {
      vehicleId: vehicleDetails.vehicleId || null,
      vin: vehicleDetails.vin || null,
      sku: vehicleDetails.sku || null,
      year: vehicleDetails.year || null,
      make: vehicleDetails.make || null,
      model: vehicleDetails.model || null,
      trim: vehicleDetails.trim || null,
      mileage: vehicleDetails.mileage || null,
      price: vehicleDetails.price || null,
      priceCurrency: vehicleDetails.priceCurrency || null,
      msrp: vehicleDetails.msrp || null,
      inventoryType: vehicleDetails.inventoryType || null,
      mainImageUrl: vehicleDetails.mainImageUrl || null,
      canonicalUrl: canonical,
      raw: vehicleDetails
    };
  } catch (e) {
    return { error: 'exception', message: String(e) };
  }
})()

(function() {
  try {
    const input = document.querySelector('input[name="search"]');
    if (!input) {
      return { error: 'search_input_not_found' };
    }
    input.focus();
    input.value = '{{search_query}}';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
    input.dispatchEvent(new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
    return { ok: true };
  } catch (e) {
    return { error: 'exception', message: String(e) };
  }
})()

(function() {
  const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"][data-qa="vehicle-ld"]'));
  const vehicles = [];
  for (const s of scripts) {
    try {
      const data = JSON.parse(s.textContent || 'null');
      if (!data) continue;
      vehicles.push({
        name: data.name || null,
        modelDate: data.modelDate || null,
        vehicleIdentificationNumber: data.vehicleIdentificationNumber || null,
        sku: data.sku || null,
        mileageFromOdometer: data.mileageFromOdometer || null,
        offers: data.offers || null,
        url: data.url || (data.offers && data.offers.url) || null
      });
    } catch (e) {
      // ignore bad JSON
    }
  }
  return { count: vehicles.length, vehicles };
})()

